function stripGaebRtfHeader20261008(value: string): string {
  const raw = String(value ?? "");
  const lines = raw.replace(/\r/g, "").split("\n");

  // Some GAEB2000 exports prepend one or more \\*... metadata lines
  // (font, converter path, MPos). Remove only this leading block; never
  // change the following technical LV wording.
  if (!/^\s*\\+\*/.test(String(lines[0] || ""))) return raw;

  return lines
    .filter((line) => !/^\s*(?:\\+\*.*|;;|\[Normal\];?.*|\[Default Paragraph Font\].*|MPos;?)\s*$/i.test(line))
    .join(" ")
    .replace(/\s+/g, " ")
    .trim();
}
function textOf(row: RlcAutonomousCalcInput): string {
  return `${stripGaebRtfHeader20261008(row.kurztext ?? "")} ${stripGaebRtfHeader20261008(row.langtext ?? "")}`.toLowerCase();
}

