      addLine(lines,"Lohn","Profilieren / Einbaudokumentation",2.5,unit);
      return finish(row,ctx,"Erdbau/Frostschutz-Baugrube","Frostschutzkies je lfm Baugrube einbauen","Frostschutz Baugrube m",lines,riskFrom(ctx,"high"),["Standardansatz 0,20 m³/m; tatsächliche Breite und Einbaudicke aus Aufmaß/Bezugsposition übernehmen."]);
