/** Specific repair rules for recurring, legacy-encoded GAEB texts. */
function calculateZeroAuditBatch15(
  row: RlcAutonomousCalcInput,
  ctx: RlcAutonomousProjectContext,
  text: string,
  _shortText: string,
  unit: string
): RlcAutonomousCalcResult | null {
  const normalizedUnit = unit.toLowerCase();
  const lines: RlcAutonomousCostLine[] = [];
  const evidence = (key: keyof typeof INTERNET_PRICE_EVIDENCE_2026) => {
    const item = INTERNET_PRICE_EVIDENCE_2026[key];
    return `Internet evidence: ${item.url} (${item.verifiedAt}); ${item.scope}`;
  };

  // Corrupted imports frequently lose the letter "s" ("erfa ung", "zu tand").
  if (["psch", "pausch", "pauschale"].includes(normalizedUnit) && /erfa(?:ss)?\s*ung.*zu(?:s)?\s*tand/.test(text)) {
    addLine(lines, "Lohn", "Bestandsaufnahme mit Auftraggeber und Straßenbaulastträger", 304, unit, evidence("bau_tariff_igbau_2026"));
    addLine(lines, "Lohn", "Fotodokumentation, Zuordnung und Protokoll", 152, unit, evidence("bau_tariff_igbau_2026"));
    addLine(lines, "Maschinen", "Kamera, Messmittel und Anfahrt", 64, unit);
    return finish(row, ctx, "Dokumentation/Zustandserfassung", "Zustandsaufnahme vor Baubeginn", "Zustand Straßen, Gelände und Anlagen dokumentieren", lines, riskFrom(ctx, "high"), ["Pauschale: Umfang, Objektanzahl und AG-Termine vor Beauftragung abgleichen."]);
  }

  if (["h", "std"].includes(normalizedUnit) && /verrechnung\s*(?:s)?\s*s?atz.*arbeit\s*kr/.test(text)) {
    addLine(lines, "Lohn", "Arbeitskraft – interner Verrechnungssatz", 38, unit, evidence("bau_tariff_igbau_2026"));
    return finish(row, ctx, "Regie/Arbeitskraft", "Mittlerer Verrechnungssatz Arbeitskräfte", "Arbeitskraft im Regiestundensatz", lines, riskFrom(ctx, "low"));
  }

  if (["st", "stk"].includes(normalizedUnit) && /beprobung.*analytik.*haufwerk/.test(text)) {
    addLine(lines, "Nachunternehmer", "Erweiterte Schadstoffanalyse je Haufwerk", 79, unit, evidence("soil_analysis_2026"));
    addLine(lines, "Lohn", "Haufwerk beproben, dokumentieren und Versand vorbereiten", 76, unit, evidence("bau_tariff_igbau_2026"));
    addLine(lines, "Nachunternehmer", "Probenlogistik/Laborversand", 20, unit);
    return finish(row, ctx, "Entsorgung/Haufwerksanalytik", "Haufwerk beproben und analysieren", "Beprobung und Analytik Haufwerk", lines, riskFrom(ctx, "high"), ["Die Laborleistung ist als veröffentlichter Analyseanker angesetzt; Parameterumfang und Anzahl Teilproben prüfen."]);
  }

  if (["m3", "m³"].includes(normalizedUnit) && /leitung(?:s)?\s*gr.*schachtbaugr.*her\s*s?t/.test(text)) {
    addLine(lines, "Lohn", "Leitungsgraben und Schachtbaugrube profilgerecht herstellen", 31, unit, evidence("bau_tariff_igbau_2026"));
    addLine(lines, "Maschinen", "Hydraulikbagger, Laden und Feinplanum", 27, unit);
    addLine(lines, "Material", "Kleinmaterial/Absicherung anteilig", 7, unit);
    return finish(row, ctx, "Erdbau/Leitungsgraben", "Leitungsgraben mit Schachtbaugrube", "Leitungsgraben und Schachtbaugrube herstellen", lines, riskFrom(ctx, "high"), ["Tiefe, Bodenklasse, Verbau, Wasserhaltung und Oberflächenwiederherstellung sind nur bei expliziter Leistungsbeschreibung einzurechnen."]);
  }

  if (["m", "lfm", "m3", "m³"].includes(normalizedUnit) && /zulage\s*handau\s*s?hub|zulage.*au\s*s?hub.*hand/.test(text)) {
    const manualAdder = ["m3", "m³"].includes(normalizedUnit) ? 46 : 46;
    addLine(lines, "Lohn", "Zulage für manuelles Lösen und Ausheben", manualAdder, unit, evidence("hand_excavation_2026"));
    addLine(lines, "Maschinen", "Kleingerät/Handtransport", 8, unit);
    return finish(row, ctx, "Erdbau/Handaushub-Zulage", "Zulage Handaushub", "Manuellen Aushub zusätzlich ausführen", lines, riskFrom(ctx, "high"), ["Zulage ohne doppelte Anrechnung des Grund-Aushubs; nur auf Anordnung und für die tatsächlich manuell ausgeführte Strecke."]);
  }

  if (["t", "to", "tonne", "tonnen"].includes(normalizedUnit) && /\bdob\b.*her\s*t/.test(text)) {
    addLine(lines, "Material", "Deckschicht ohne Bindemittel – Gesteinskörnung", 24.9, unit, evidence("aggregates_glueck_2026"));
    addLine(lines, "Lohn", "Einbauen und profilieren", 8.1, unit, evidence("bau_tariff_igbau_2026"));
    addLine(lines, "Maschinen", "Transport, Walze und Gerät anteilig", 6.0, unit);
    return finish(row, ctx, "Straßenbau/DoB", "Deckschicht ohne Bindemittel herstellen", "DoB liefern, einbauen und verdichten", lines, riskFrom(ctx, "high"), ["Schichtdicke, Einbaufläche, Transportentfernung und Verdichtungsanforderung sind projektabhängig zu prüfen."]);
  }

  if (["t", "to", "tonne", "tonnen"].includes(normalizedUnit) && /betonkies\s*[0o]\/32/.test(text)) {
    addLine(lines, "Material", "Betonkies 0/32 liefern", 24.9, unit, evidence("aggregates_glueck_2026"));
    return finish(row, ctx, "Material/Gesteinskörnung", "Betonkies 0/32 liefern", "Betonkies 0/32", lines, riskFrom(ctx, "medium"));
  }

  if (["m3", "m³"].includes(normalizedUnit) && /kippgeb.hr|kippgebuehr/.test(text) && /z0|unbelastet/.test(text)) {
    addLine(lines, "Entsorgung", "Kippgebühr unbelasteter mineralischer Boden Z0", 16, unit, evidence("soil_disposal_2026"));
    return finish(row, ctx, "Entsorgung/Kippgebühr", "Mineralischer Boden Z0", "Kippgebühr Z0", lines, riskFrom(ctx, "high"), ["Umrechnung aus veröffentlichtem Tonnenpreis mit 1,60 t/m³ Referenzdichte; Materialfeuchte und Wiegeschein prüfen."]);
  }

  return null;
}

