function calculateZeroAuditBatch29(
  row: RlcAutonomousCalcInput,
  ctx: RlcAutonomousProjectContext,
  text: string,
  shortText: string,
  unit: string
): RlcAutonomousCalcResult | null {
  const lines: RlcAutonomousCostLine[] = [];
  const u=unit.toLowerCase();

  if (["st","stk","stck","st."].includes(u) && hasAny(shortText,["zl seitlicher zulauf","seitlicher zulauf"])) {
    addLine(lines,"Material","Anschlussformstück / Dichtung / Kleinmaterial",68,unit);
    addLine(lines,"Lohn","Seitlichen Zulauf herstellen / abdichten",52,unit);
    addLine(lines,"Maschinen","Kernbohr-/Schneidgerät anteilig",22,unit);
    return finish(row,ctx,"Kanalbau/Seitenzulauf","Seitlichen Zulauf herstellen","Seitlicher Zulauf",lines,riskFrom(ctx,"high"),["DN, Werkstoff und Schachtsystem aus Langtext/Bezugsposition prüfen."]);
  }

  if (["st","stk","stck","st."].includes(u) && hasAny(shortText,["gullyanschluss"])) {
    const dn=extractNominalDiameterMm(text)||100;
    addLine(lines,"Material",`Anschlussformstück/Dichtung DN${dn}`,42,unit);
    addLine(lines,"Lohn","Gullyanschluss herstellen und abdichten",48,unit);
    addLine(lines,"Maschinen","Kleinbagger/Kernbohrung anteilig",28,unit);
    return finish(row,ctx,"Entwaesserung/Gullyanschluss",`Gullyanschluss DN${dn} herstellen`,`Gullyanschluss DN${dn}`,lines,riskFrom(ctx,"medium"));
  }

  if (["st","stk","stck","st."].includes(u) && hasAny(shortText,["mehrpreis für ansetzen gerät","mehrpreis fuer ansetzen geraet","ansetzen gerät an einem","ansetzen geraet an einem"])) {
    addLine(lines,"Maschinen","Gerät umsetzen / neu ansetzen",55,unit);
    addLine(lines,"Lohn","Einrichten / Sichern / Bedienung",25,unit);
    return finish(row,ctx,"Kanalbau/Geraet-Ansetzen-Zulage","Mehrpreis Gerät an Schacht neu ansetzen","Gerät ansetzen Zulage",lines,riskFrom(ctx,"medium"));
  }

  if (["m","lfm"].includes(u) && hasAny(shortText,["inspektion sw-kanalleitungen","inspektion rw-kanalleitungen","tv kanaluntersuchung"])) {
    const dn=extractNominalDiameterMm(text)||160;
    addLine(lines,"Nachunternehmer",`TV-Kanalinspektion DN${dn} inkl. Kamera`,4.6,unit);
    addLine(lines,"Lohn","Dokumentation / Befundzuordnung anteilig",1.6,unit);
    return finish(row,ctx,"Kanalservice/TV-Inspektion",`TV-Inspektion DN${dn}`,`TV-Inspektion DN${dn}`,lines,riskFrom(ctx,"medium"),["An-/Abfahrt und Reinigung separat prüfen."]);
  }

  if (["m3","m³"].includes(u) && hasAny(shortText,["kieschüttung 16/32","kies 16/32","filterstabile schutzschicht","kiesmaterial als filterschicht"])) {
    addLine(lines,"Material","Kies 16/32 bzw. Filterkies, ca. 1,6 t/m³",35.68,unit,"Glück Kies 2026: 22,30 EUR/t");
    addLine(lines,"Maschinen","Transport/Einbau/Verdichtung anteilig",14,unit);
    addLine(lines,"Lohn","Profilieren / Nacharbeit",5,unit);
    return finish(row,ctx,"Erdbau/Kies-Filterschicht","Kies-/Filterschicht liefern und einbauen","Kies/Filter 16-32",lines,riskFrom(ctx,"medium"));
  }

  if (["m2","m²"].includes(u) && hasAny(shortText,["plattenbelag aus beton aufnehmen","betonpflaster rückbauen","betonpflaster rueckbauen"])) {
    addLine(lines,"Lohn","Betonplatten/-pflaster aufnehmen und sortieren",14,unit);
    addLine(lines,"Maschinen","Minibagger / Palettengabel / innerer Transport",6,unit);
    addLine(lines,"Entsorgung","Restmaterial verwerten anteilig",3,unit);
    return finish(row,ctx,"Abbruch/Betonpflaster","Betonplatten/-pflaster aufnehmen","Betonpflaster Rückbau",lines,riskFrom(ctx,"medium"));
  }

  if (["m2","m²"].includes(u) && hasAny(shortText,["plattenbelag m. pl. des ag herst","plattenbelag mit platten des ag"])) {
    addLine(lines,"Material","Bettung 0/5 und Fugenmaterial",8.5,unit);
    addLine(lines,"Lohn","AG-Platten fördern, verlegen, ausrichten, verfugen",27,unit);
    addLine(lines,"Maschinen","Rüttel-/Schneidgerät anteilig",4.5,unit);
    return finish(row,ctx,"Straßenbau/Betonplatten-AG","AG-Platten wieder einbauen","Betonplatten AG",lines,riskFrom(ctx,"medium"),["Plattenmaterial = 0, da AG-beigestellt."]);
  }

  if (["m","lfm"].includes(u) && hasAny(shortText,["streifen aus natursteinen ausbauen","einzeiler ausbauen"])) {
    addLine(lines,"Lohn","Naturstein-Einzeiler aufnehmen / säubern / sortieren",10,unit);
    addLine(lines,"Maschinen","Kleingerät / innerer Transport",3.5,unit);
    return finish(row,ctx,"Abbruch/Naturstein-Einzeiler","Naturstein-Einzeiler ausbauen","Einzeiler Rückbau",lines,riskFrom(ctx,"medium"));
  }

  if (["m","lfm"].includes(u) && hasAny(shortText,["streifen aus natursteinen wieder herstellen","einzeiler wieder herstellen"])) {
    addLine(lines,"Material","Bettung/Fugenmaterial",4.5,unit);
    addLine(lines,"Lohn","Gelagerte Natursteine setzen / ausrichten / verfugen",18,unit);
    addLine(lines,"Maschinen","Kleingerät / Verdichtung",3.5,unit);
    return finish(row,ctx,"Straßenbau/Naturstein-Einzeiler","Naturstein-Einzeiler wiederherstellen","Einzeiler Wiedereinbau",lines,riskFrom(ctx,"medium"));
  }

  if (["m2","m²"].includes(u) && hasAny(shortText,["ortbeton schutzschicht unbewehrt c12/15","schutzschicht unbewehrt c12/15"])) {
    const cmM=(text.match(/(?:d|dicke|stärke|staerke)\s*(?:=|:)?\s*(\d+(?:[,.]\d+)?)\s*cm/i)||[])[1];
    const cm=cmM?Number(cmM.replace(',','.')):15; const vol=cm/100;
    addLine(lines,"Material",`Beton C12/15 ca. ${cm} cm`,155*vol,unit,"2026 Transportbeton-Marktanker");
    addLine(lines,"Lohn","Einbringen / Abziehen / Nachbehandlung",9,unit);
    addLine(lines,"Maschinen","Betonhandling / Kleingerät",4.5,unit);
    return finish(row,ctx,"Betonbau/Schutzschicht","Unbewehrte Betonschutzschicht herstellen","Betonschutzschicht",lines,riskFrom(ctx,cmM?"medium":"high"));
  }

  if (["m3","m³"].includes(u) && hasAny(shortText,["verfüllen baugrube","verfuellen baugrube","wiederverfüllen von schächten","wiederverfuellen von schaechten","wiederverfüllen von aushubmaterial","wiederverfuellen von aushubmaterial"])) {
    const supplied=hasAny(text,["boden liefern","material liefern","fremdmaterial"]);
    if(supplied) addLine(lines,"Material","Geeignetes Verfüllmaterial",24,unit);
    addLine(lines,"Maschinen","Material aufnehmen / lagenweise einbauen / verdichten",11.5,unit);
    addLine(lines,"Lohn","Einweisen / Randnacharbeit / Verdichtungskontrolle",3.5,unit);
    return finish(row,ctx,"Erdbau/Baugruben-Verfuellung",supplied?"Baugrube mit Liefermaterial verfüllen":"Baugrube mit vorhandenem Material verfüllen","Baugrubenverfüllung",lines,riskFrom(ctx,"medium"));
  }

  if (["h","std","stunde","stunden"].includes(u) && hasAny(shortText,["abbruchhammer 15 - 30 kg","abbruchhammer 15-30 kg"])) {
    addLine(lines,"Maschinen","Abbruchhammer 15-30 kg inkl. Verschleiß",18,unit);
    return finish(row,ctx,"Regie/Geraet","Abbruchhammer 15-30 kg","Abbruchhammer",lines,riskFrom(ctx,"low"));
  }

  if (["h","std","stunde","stunden"].includes(u) && hasAny(shortText,["stahlschweißer mit fahrzeug","stahlschweisser mit fahrzeug"])) {
    addLine(lines,"Lohn","Stahlschweißer",PERSONNEL_INTERNAL_COST_2026.facharbeiter_lg4,unit);
    addLine(lines,"Maschinen","Montagefahrzeug / Schweißgerät anteilig",22,unit);
    return finish(row,ctx,"Regie/Stahlschweisser","Stahlschweißer mit Fahrzeug","Stahlschweißer",lines,riskFrom(ctx,"low"));
  }

  return null;
}


function calculateZeroAuditBatch30(
  row: RlcAutonomousCalcInput,
  ctx: RlcAutonomousProjectContext,
  text: string,
  shortText: string,
  unit: string
): RlcAutonomousCalcResult | null {
  const lines: RlcAutonomousCostLine[]=[];
  const u=unit.toLowerCase();
  const isSt=["st","stk","stck","st."].includes(u);
  const plantToken=hasAny(shortText,["acer ","quercus ","tilia ","betula ","prunus ","malus ","sophora ","ostrya ","zelkova ","fraxinus ","amelanchier ","cornus ","salix ","ribes ","rhamnus ","spiraea ","geranium ","kalimeris ","potentilla ","molinia ","pulmonaria ","aster ","carex ","sedum ","salvia ","lavendula ","epimedium ","polypodium ","crocus ","muscari ","scilla ","tulipa ","euphorbia ","knautia ","veronica ","sesleria ","campanula ","helleborus ","hosta ","luzula ","calamagrostis ","catananche ","linum ","lychnis ","scabiosa ","calamintha ","hieracium ","waldsteinia ","anthericum ","festuca ","perovskia ","phlomis ","stipa ","verbascum "]);
  if(isSt && plantToken){
    const stu=(text.match(/stu\s*(\d{1,2})\s*[-–]\s*(\d{1,2})/i)||[]);
    const tree=Boolean(stu.length)||hasAny(text,["hochsta","hochstamm","m.db","mdb","drahtballen","heister","solitärbaum","solitaerbaum","4xv","5xv","6xv"]);
    if(tree){
      const lo=stu[1]?Number(stu[1]):12;
      let material=206;
      if(lo>=25) material=1470; else if(lo>=20) material=520; else if(lo>=18) material=380; else if(lo>=16) material=290; else if(lo>=14) material=245; else if(lo>=12) material=210;
      addLine(lines,"Material",`Baum ${stu[1]?`StU ${stu[1]}-${stu[2]}`:"Qualität gemäß LV"}`,material,unit,"Aktueller Marktanker 2026: deutsche Baumschulen, netto aus öffentlichen Bruttopreisen abgeleitet");
      addLine(lines,"Lohn","Baum pflanzen / ausrichten / anbinden",85,unit);
      addLine(lines,"Maschinen","Bagger/Kran/Handling anteilig",55,unit);
      addLine(lines,"Material","Pflanzpfähle/Bindung/Bodenverbesserung anteilig",32,unit);
      return finish(row,ctx,"Landschaftsbau/Baum-Lieferung-Pflanzung","Baum liefern und pflanzen","Baum Lieferung/Pflanzung",lines,riskFrom(ctx,"high"),["Art, exakte Baumschulqualität und Ballen können den Materialpreis stark verändern; aktuelle Lieferantenanfrage vor Angebotsfreigabe."]);
    }
    const shrub=hasAny(text,["strauch","solitär","solitaer","c 3","c3","c 5","c5","60-100","80-100","100-125"]);
    if(shrub){
      addLine(lines,"Material","Strauch/Gehölz gemäß LV-Qualität",18,unit,"2026 Marktansatz; genaue Sorte/Topfgröße vor Freigabe prüfen");
      addLine(lines,"Lohn","Pflanzen / angießen / Nacharbeit",8,unit);
      addLine(lines,"Maschinen","Transport/Handling anteilig",2.5,unit);
      return finish(row,ctx,"Landschaftsbau/Gehölz-Lieferung-Pflanzung","Gehölz liefern und pflanzen","Gehölz Lieferung/Pflanzung",lines,riskFrom(ctx,"high"));
    }
    addLine(lines,"Material","Staude/Gras/Bodendecker gemäß LV",3.5,unit,"2026 Marktanker: professionelle Staudenangebote; Sorten-/Topfgröße prüfen");
    addLine(lines,"Lohn","Staude pflanzen / angießen",4.2,unit);
    addLine(lines,"Maschinen","Transport/Handling anteilig",0.8,unit);
    return finish(row,ctx,"Landschaftsbau/Stauden-Lieferung-Pflanzung","Staude/Gras liefern und pflanzen","Stauden Lieferung/Pflanzung",lines,riskFrom(ctx,"high"));
  }

  if (["h","std","stunde","stunden"].includes(u) && hasAny(shortText,["bohrlafette"])) {
    addLine(lines,"Maschinen","Bohrlafette inkl. Verschleiß/Betrieb",85,unit);
    addLine(lines,"Lohn","Bedienpersonal",PERSONNEL_INTERNAL_COST_2026.facharbeiter_lg4,unit);
    return finish(row,ctx,"Regie/Bohrlafette","Bohrlafette mit Bedienung","Bohrlafette",lines,riskFrom(ctx,"medium"));
  }
  if (["h","std","stunde","stunden"].includes(u) && hasAny(shortText,["explosionsstampframme"])) {
    addLine(lines,"Maschinen","Explosionsstampframme inkl. Betrieb",48,unit);
    addLine(lines,"Lohn","Bedienpersonal",PERSONNEL_INTERNAL_COST_2026.facharbeiter_lg4,unit);
    return finish(row,ctx,"Regie/Stampframme","Explosionsstampframme mit Bedienung","Stampframme",lines,riskFrom(ctx,"medium"));
  }

  if (["m3","m³"].includes(u) && hasAny(shortText,["bodenplatte betonieren"])) {
    addLine(lines,"Material","Transportbeton C25/30 Referenz",172,unit,"2026 Transportbeton-Marktanker");
    addLine(lines,"Lohn","Einbringen / Verdichten / Abziehen",32,unit);
    addLine(lines,"Maschinen","Betonpumpe/Kleingerät anteilig",18,unit);
    return finish(row,ctx,"Betonbau/Bodenplatte","Bodenplatte betonieren","Bodenplatte Beton",lines,riskFrom(ctx,"high"),["Bewehrung und Schalung separat prüfen."]);
  }
  if (["m3","m³"].includes(u) && hasAny(shortText,["boden bk5 laden","transportieren, wiedereinbauen","transportieren wiedereinbauen"])) {
    addLine(lines,"Maschinen","Boden laden / kurzer Baustellentransport / wiedereinbauen",13.5,unit);
    addLine(lines,"Maschinen","Verdichten",4.5,unit);
    addLine(lines,"Lohn","Einweisen / Nacharbeit",3.5,unit);
    return finish(row,ctx,"Erdbau/Boden-Umlagerung","Boden laden, innerbaustellisch transportieren und wiedereinbauen","Boden Umlagerung",lines,riskFrom(ctx,"medium"));
  }
  if (["m2","m²"].includes(u) && hasAny(shortText,["hecke wurzelstöcke roden","hecke wurzelstoecke roden"])) {
    addLine(lines,"Maschinen","Minibagger/Stubbenfräse/Häcksler anteilig",11,unit);
    addLine(lines,"Lohn","Hecke/Wurzelstöcke roden / aufnehmen",8,unit);
    addLine(lines,"Entsorgung","Grüngut/Wurzelholz verwerten anteilig",4,unit);
    return finish(row,ctx,"Landschaftsbau/Heckenrodung","Hecke inkl. Wurzelstöcke roden","Heckenrodung",lines,riskFrom(ctx,"medium"));
  }
  return null;
}


