function resolveCentralParametricPipeRecovery20261008(
  row: RlcAutonomousCalcInput,
  ctx: RlcAutonomousProjectContext,
  text: string,
  shortText: string,
  unit: string
): RlcAutonomousCalcResult | null {
  const u = canonicalGaebUnit20261008(unit);
  if (u !== "m") return null;

  const normalized = normalizeMatchText20260928(text);
  const isPipe = /\b(?:rohr|rohrleitung|druckrohr|wasserleitung|kanalrohr|abwasserrohr|leitung)\b/.test(normalized);
  if (!isPipe) return null;
  if (!/\b(?:liefern|lieferung|verlegen|einbauen|montieren|herstellen)\b/.test(normalized)) return null;
  if (/\b(?:wie vor|vorposition|alternative|wahlposition|nur zulage|ohne rohrlieferung|nur verlegen)\b/.test(normalized) || /\bpos\.?\s*\[?\d/.test(normalized)) return null;

  // Central recovery is intentionally strict: tasks that modify, remove,
  // surround, test or merely reference a pipe must stay in their own family.
  if (/\b(?:abbrechen|ausbauen|rueckbau|ummantel|bettung|verfuell|hinterfuell|pruef|spuel|reinigen|zuschlag|zulage|anarbeiten|sichern|stilllegen)\b/.test(normalized)) {
    return null;
  }

  const lines: RlcAutonomousCostLine[] = [];

  if (/\b(?:pe|pe hd|hdpe|pe100|pe 100|polyethylen)\b/.test(normalized)) {
    const od = extractPeOuterDiameterMm(text);
    if (!od || od < 20 || od > 800) return null;
    const pressureClass = pePressureClassFromText(text);
    const material = peMaterialPriceEurPerM(od, pressureClass);
    const install = peInstallationAddersEurPerM(od, pressureClass);
    addLine(lines, "Material", `PE100-RC Druckrohr DA${od} ${pressureClass}`, material, unit, "RLC 2026 PE resource table");
    addLine(lines, "Lohn", "Rohr ausrichten / verlegen", install.labor, unit);
    addLine(lines, "Lohn", "Verbindung / Schweiß- bzw. Fügeleistung", install.jointing, unit);
    addLine(lines, "Maschinen", "Rohrhandling / Kleingerät", install.machine, unit);
    return finish(
      row, ctx,
      "Wasserleitungsbau/PE-Druckrohr",
      `PE-Druckrohr DA${od} ${pressureClass} liefern und verlegen`,
      `PE-Rohr DA${od} ${pressureClass}`,
      lines,
      riskFrom(ctx, "medium"),
      ["Zentrale parametrische V2-Familie; Graben, Bettung, Formstücke und Druckprüfung nur enthalten, wenn nicht separat ausgeschrieben."]
    );
  }

  const dn = extractNominalDiameterMm(text);
  if (!dn || dn < 80 || dn > 1600) return null;

  if (/\b(?:kg2000|pp md|pp rohr|polypropylen|sn16|sn 16)\b/.test(normalized)) {
    const ep = kgPpSn16TotalEurPerM(dn);
    addLine(lines, "Material", `PP/KG2000 Rohr DN${dn}`, ep * 0.72, unit, "RLC 2026 PP/KG resource table");
    addLine(lines, "Lohn", "Rohr verlegen / Muffenverbindung", ep * 0.18, unit);
    addLine(lines, "Maschinen", "Rohrhandling / Kleingerät", ep * 0.10, unit);
    return finish(row, ctx, "Kanalbau/PP-Rohr", `PP/KG2000 Rohr DN${dn} liefern und verlegen`, `PP-Rohr DN${dn}`, lines, riskFrom(ctx, "medium"));
  }

  if (/\b(?:kg rohr|pvc rohr|pvc u|kanalgrundrohr|sn8|sn 8)\b/.test(normalized)) {
    const ep = kgPvcSn8TotalEurPerM(dn);
    addLine(lines, "Material", `PVC/KG SN8 Rohr DN${dn}`, ep * 0.72, unit, "RLC 2026 PVC/KG resource table");
    addLine(lines, "Lohn", "Rohr verlegen / Muffenverbindung", ep * 0.18, unit);
    addLine(lines, "Maschinen", "Rohrhandling / Kleingerät", ep * 0.10, unit);
    return finish(row, ctx, "Kanalbau/PVC-KG-Rohr", `PVC/KG SN8 Rohr DN${dn} liefern und verlegen`, `PVC/KG Rohr DN${dn}`, lines, riskFrom(ctx, "medium"));
  }

  if (/\b(?:steinzeug|stz)\b/.test(normalized)) {
    const ep = steinzeugTotalEurPerM(dn);
    addLine(lines, "Material", `Steinzeugrohr DN${dn}`, ep * 0.72, unit, "RLC 2026 Steinzeug resource table");
    addLine(lines, "Lohn", "Rohr verlegen / Muffenverbindung", ep * 0.18, unit);
    addLine(lines, "Maschinen", "Rohrhandling / Hebehilfe", ep * 0.10, unit);
    return finish(row, ctx, "Kanalbau/Steinzeugrohr", `Steinzeugrohr DN${dn} liefern und verlegen`, `Steinzeug DN${dn}`, lines, riskFrom(ctx, "medium"));
  }

  if (/\b(?:betonrohr|stahlbetonrohr)\b/.test(normalized)) {
    const ep = betonrohrTotalEurPerM(dn);
    addLine(lines, "Material", `Betonrohr DN${dn}`, ep * 0.70, unit, "RLC 2026 Betonrohr resource table");
    addLine(lines, "Lohn", "Rohr verlegen / Fuge herstellen", ep * 0.15, unit);
    addLine(lines, "Maschinen", "Kran-/Baggerhandling", ep * 0.15, unit);
    return finish(row, ctx, "Kanalbau/Betonrohr", `Betonrohr DN${dn} liefern und verlegen`, `Betonrohr DN${dn}`, lines, riskFrom(ctx, "medium"));
  }

  if (/\b(?:ggg|duktil|gussrohr|guss rohr)\b/.test(normalized)) {
    const material = gggMaterialAndAccessoryEurPerM(dn);
    const install = gggInstallationAddersEurPerM(dn);
    addLine(lines, "Material", `Duktiles Gussrohr DN${dn}`, material, unit, "RLC 2026 GGG resource table");
    addLine(lines, "Lohn", "Rohr verlegen / Verbindung", install.labor, unit);
    addLine(lines, "Maschinen", "Rohrhandling / Hebehilfe", install.machine, unit);
    return finish(row, ctx, "Wasserleitungsbau/GGG-Rohr", `Duktiles Gussrohr DN${dn} liefern und verlegen`, `GGG Rohr DN${dn}`, lines, riskFrom(ctx, "medium"));
  }

  return null;
}

function resolveStrictSurfaceResources20261008(row: RlcAutonomousCalcInput, ctx: RlcAutonomousProjectContext, text: string, shortText: string, unit: string): RlcAutonomousCalcResult | null {
  const u = canonicalGaebUnit20261008(unit);
  const tx = normalizeMatchText20260928(text);
  const st = normalizeMatchText20260928(shortText);
  if (/\b(?:alternative|wahlposition|zulage|zuschlag|wie vor|vorposition|rueckbau|abbruch|ausbauen|aufnehmen|entsorgen)\b/.test(tx) || /\bpos\.?\s*\[?\d/.test(tx)) return null;
  // Existing vetted V2 1-Zeiler recipe: accept GAEB spacing / spelling variants.
  if (u === "m" && /granitkleinstein(?:pflaster)?\s*1\s*[- ]\s*zeiler\b/.test(st) && !/\b(?:nur ausbau|entfernen|aufnehmen|rueckbau)\b/.test(tx)) {
    const lines: RlcAutonomousCostLine[] = [];
    addLine(lines, "Material", "Granitkleinstein und Bettung 1-Zeiler", 14, u);
    addLine(lines, "Lohn", "Einzeiler setzen / verfugen", 16, u);
    addLine(lines, "Maschinen", "Schneiden / Handling", 3, u);
    return finish(row, ctx, "Pflaster/Granitkleinstein-1Zeiler", "Granitkleinstein Einzeiler setzen", "Granitkleinstein 1-Zeiler", lines, riskFrom(ctx, "medium"), ["Steinformate, Fugenart und Bettung anhand des LV pruefen."]);
  }
  if (u === "m2" && /\b(?:betonverbundpflaster|betonpflastersteine)\b/.test(st) && /\b(?:liefern|verlegen|einbauen|herstellen)\b/.test(tx)) {
    const cm = tx.match(/(?:dicke|staerke|d)\s*(?:=|von)?\s*(6|8|10|12)\s*cm\b/);
    if (!cm) return null;
    const thickness = Number(cm[1]);
    const lines: RlcAutonomousCostLine[] = [];
    // Established V2 2026 resources: Betonpflaster including bedding/joints, installation, compaction.
    addLine(lines, "Material", `Betonverbundpflaster ${thickness} cm inkl. Bettung/Fuge`, 58 * thickness / 8, u);
    addLine(lines, "Lohn", "Pflaster verlegen / schneiden / verfugen", 42, u);
    addLine(lines, "Maschinen", "Ruettel- / Schneidtechnik", 6.5, u);
    return finish(row, ctx, "Pflaster/Betonverbundpflaster-V2", `Betonverbundpflaster ${thickness} cm liefern und verlegen`, "Betonpflaster m2", lines, riskFrom(ctx, "medium"));
  }
  return null;
}

