function resolveGenericKurztextFromLangtext20260929(
  row: RlcAutonomousCalcInput,
  ctx: RlcAutonomousProjectContext,
  shortText: string
): RlcAutonomousCalcResult | null {
  const generic = /^(senkrecht|waagerecht|horizontal|vertikal|vermessung|zuschlag|zulage|erschwerniszuschlag|instandhaltung|freitext(?:\s*\.\.\.)?)$/i.test(shortText.trim())
    || /^beton c\s*\d+\s*[\/ ]\s*\d+$/i.test(shortText.trim())
    || /^steinst(?:ärke|aerke|„rke)\s*\d+(?:[,.]\d+)?\s*mm$/i.test(shortText.trim());
  if (!generic) return null;
  const long = String(row.langtext ?? "").replace(/\s+/g, " ").trim();
  if (long.length < 60) return null;
  const shortNorm = normalizeMatchText20260928(shortText);
  const longNorm = normalizeMatchText20260928(long);
  if (!longNorm || longNorm === shortNorm) return null;
  const synthetic: RlcAutonomousCalcInput = {
    ...row,
    kurztext: long,
    langtext: long,
  };
  const resolved = calculateTiefbauFamilyCatalog(synthetic, ctx, []);
  if (!resolved || resolved.unitPrice <= 0) return null;
  resolved.riskLevel = "high";
  resolved.confidence = Math.min(resolved.confidence ?? 0.8, 0.84);
  resolved.calculationStatus = statusFromRisk("high");
  resolved.warnings = Array.from(new Set([
    ...(resolved.warnings || []),
    "Kurztext war technisch zu allgemein; Kalkulation wurde aus dem vollständigen Langtext neu aufgebaut."
  ]));
  resolved.aiReason += " Generischer Kurztext: Langtext als technische Primärquelle verwendet; keine EP-Vererbung.";
  return resolved;
}

function resolveInheritedVariant20260927(
  row: RlcAutonomousCalcInput,
  ctx: RlcAutonomousProjectContext,
  allRows: RlcAutonomousCalcInput[],
  rowIndex: number,
  previousRow: RlcAutonomousCalcInput | null,
  text: string,
  shortText: string,
  unit: string
): RlcAutonomousCalcResult | null {
  const genericLangtextRecovery = resolveGenericKurztextFromLangtext20260929(row, ctx, shortText);
  if (genericLangtextRecovery) return genericLangtextRecovery;

  const contextualFormpiece = /^(bogen|abzweig)\s+dn\s*\d+/i.test(shortText.trim());
  const orientationOnly = /^(senkrecht|waagerecht|horizontal|vertikal)$/i.test(shortText.trim());
  const thicknessOnly = /^steinst(?:ärke|aerke|„rke)\s*\d+(?:[,.]\d+)?\s*mm$/i.test(shortText.trim());
  const freitextPlaceholder = /^freitext(?:\s*\.\.\.)?$/i.test(shortText.trim()) && String(row.langtext ?? "").trim().length < 20;
  const isInheritedVariant =
    contextualFormpiece ||
    orientationOnly ||
    thicknessOnly ||
    freitextPlaceholder ||
    hasAny(shortText, ["wie pos. vorher", "wie pos vorher", "wie vor", "jedoch flächen", "jedoch flaechen"]) ||
    hasAny(text, ["position wie vor, jedoch", "position wie vor jedoch", "wie pos. vor jedoch", "wie pos vor jedoch", "wie vor beschrieben", "sonst wie vor näher beschrieben", "sonst wie vor naeher beschrieben", "wie vorherige pos., jedoch", "wie vorherige pos jedoch"]);
  if (!isInheritedVariant || allRows.length <= 1) return null;

  const positionParts = (value: unknown): number[] =>
    (String(value ?? "").match(/\d+/g) || []).map((x) => Number(x));
  const comparePosition = (a: RlcAutonomousCalcInput, b: RlcAutonomousCalcInput): number => {
    const aa = positionParts((a as any).posNr);
    const bb = positionParts((b as any).posNr);
    const max = Math.max(aa.length, bb.length);
    for (let i = 0; i < max; i++) {
      const av = aa[i] ?? -1;
      const bv = bb[i] ?? -1;
      if (av !== bv) return av - bv;
    }
    return s((a as any).posNr).localeCompare(s((b as any).posNr), "de");
  };
  const orderedRows = [...allRows].sort(comparePosition);
  const orderedIndex = orderedRows.findIndex((candidate) => {
    const sameId = s((candidate as any).id) && s((candidate as any).id) === s((row as any).id);
    const samePos = s((candidate as any).posNr) && s((candidate as any).posNr) === s((row as any).posNr);
    return Boolean(sameId || samePos);
  });
  if (orderedIndex <= 0) return null;

  const currentUnit = s(row.einheit || "").toLowerCase();
  const baseCandidates = orderedRows
    .slice(Math.max(0, orderedIndex - 20), orderedIndex)
    .reverse()
    .filter((candidate) => {
      const ct = textOf(candidate);
      const cshort = s(candidate.kurztext).toLowerCase();
      const cu = s(candidate.einheit || "").toLowerCase();
      const derivative = hasAny(ct, [
        "wie pos. vorher", "wie pos vorher", "position wie vor", "jedoch flächen", "jedoch flaechen", "wie vor jedoch",
        "zulage zu pos", "zulage zu position", "mehrtiefe", "mehrstärke", "mehrstaerke", "wie vor beschrieben", "sonst wie vor näher beschrieben", "sonst wie vor naeher beschrieben",
        "senkrecht", "waagerecht", "horizontal", "vertikal", "freitext", "steinstärke", "steinstaerke", "steinst„rke"
      ]);
      const structural = hasAny(cshort, ["titel", "abschnitt", "summe"]);
      return Boolean(ct && !derivative && !structural && (!currentUnit || !cu || cu === currentUnit));
    });
  if (!baseCandidates.length) return null;

  if (contextualFormpiece) {
    const prior = orderedRows.slice(Math.max(0, orderedIndex - 20), orderedIndex);
    const peContext = [...prior].reverse().find((candidate) => hasAny(textOf(candidate), ["pe-hd", "pe hd", "din 19535", "din 19537", "din 8074", "din en 12201", "heizspiegel-stumpf", "elektromuffenschwei"]));
    if (peContext) {
      const dn = extractNominalDiameterMm(text) || 100;
      const branch = hasAny(shortText, ["abzweig"]);
      const flines: RlcAutonomousCostLine[] = [];
      const mat = branch ? (dn <= 100 ? 42 : dn <= 150 ? 78 : 125) : (dn <= 100 ? 75 : dn <= 150 ? 118 : 175);
      addLine(flines, "Material", `${branch ? "PE-HD Abzweig" : "PE-HD Bogen"} DN${dn}`, mat, unit, "Marktanker 2026: SIMONA/GWE PE-HD Formstücke");
      addLine(flines, "Lohn", `${branch ? "Abzweig" : "Bogen"} einpassen / Stumpfschweißen`, branch ? 34 : 28, unit);
      addLine(flines, "Maschinen", "Heizspiegel-/Schweißgerät, Vorbereitung", 12, unit);
      return finish(row, ctx, "Leitungsbau/PE-HD-Formstück", `${branch ? "PE-HD Abzweig" : "PE-HD Bogen"} DN${dn} liefern und einbauen`, `${branch ? "PE-HD Abzweig" : "PE-HD Bogen"} DN${dn}`, flines, riskFrom(ctx, "medium"), ["Werkstoff und Schweißverfahren aus vorhergehender PE-HD-Position übernommen; SDR/PN, Winkel und Gleich-/Reduzierabzweig prüfen."]);
    }
    const ppContext = [...prior].reverse().find((candidate) => hasAny(textOf(candidate), ["kanalrohr aus pp", "din en 1852", "kg2000", "pp-rohr", "pp rohr"]));
    if (ppContext) {
      const dn = extractNominalDiameterMm(text) || 110;
      const branch = hasAny(shortText, ["abzweig"]);
      const flines: RlcAutonomousCostLine[] = [];
      const bendPrices:Record<number,number>={100:5.30,110:5.30,125:6.70,150:12.90,160:12.90,200:27.15,250:67.90,315:107.90};
      const branchPrices:Record<number,number>={100:10.20,110:10.20,125:15.50,150:21.80,160:21.80,200:56.55,250:195.45,315:345.00};
      const mat=(branch?branchPrices[dn]:bendPrices[dn]) ?? Math.max(branch?22:12,dn*(branch?0.45:0.28));
      addLine(flines,"Material",`${branch?"PP/KG2000 Abzweig":"PP/KG2000 Bogen"} DN${dn}`,mat,unit,"Heinlein/Ostendorf Preisliste 2026");
      addLine(flines,"Lohn",`${branch?"Abzweig":"Bogen"} einpassen / Dichtung reinigen / stecken`,branch?20:16,unit);
      if(dn>=315)addLine(flines,"Maschinen","Handling/Hebehilfe",8,unit);
      return finish(row,ctx,"Kanalbau/PP-Formstück",`${branch?"PP-Abzweig":"PP-Bogen"} DN${dn} liefern und einbauen`,`${branch?"PP-Abzweig":"PP-Bogen"} DN${dn}`,flines,riskFrom(ctx,"medium"),["Werkstoff PP/KG2000 aus vorhergehender Rohrposition übernommen; SN/Typ, Winkel und Reduzierung prüfen."]);
    }
  }

  const currentModifier = `${row.kurztext ?? ""} ${row.langtext ?? ""}`
    .replace(/wie\s+pos\.?\s*(?:vorher|vor)\s*,?\s*jedoch/ig, " ")
    .replace(/position\s+wie\s+vor\s*,?\s*jedoch/ig, " ")
    .trim();
  let baseRow: RlcAutonomousCalcInput | null = null;
  let inherited: RlcAutonomousCalcResult | null = null;
  for (const candidate of baseCandidates) {
    const inheritedRow: RlcAutonomousCalcInput = {
      ...row,
      kurztext: candidate.kurztext,
      langtext: `${candidate.langtext ?? ""}\nVARIANTE: ${currentModifier}`,
    };
    const candidateResult = calculateTiefbauFamilyCatalog(inheritedRow, ctx, []);
    if (candidateResult && candidateResult.unitPrice > 0) {
      baseRow = candidate;
      inherited = candidateResult;
      break;
    }
  }
  if (!baseRow || !inherited) return null;

  if (thicknessOnly) {
    const currentMm = Number((shortText.match(/(\d+(?:[,.]\d+)?)\s*mm/i) || [])[1]?.replace(",", ".") || 0);
    const baseTxt = `${baseRow.kurztext ?? ""} ${baseRow.langtext ?? ""}`;
    const baseMm = Number((baseTxt.match(/(\d+(?:[,.]\d+)?)\s*mm/i) || [])[1]?.replace(",", ".") || 0);
    if (currentMm > 0 && baseMm > 0 && Math.abs(currentMm - baseMm) > 0.1) {
      const factor = currentMm / baseMm;
      for (const line of inherited.costLines) {
        if (String(line.group) === "Material") {
          line.unitPrice = round2(n(line.unitPrice) * factor);
          line.total = round2(n(line.total) * factor);
        }
      }
      inherited.unitPrice = round2(sum(inherited.costLines));
      inherited.total = round2(inherited.unitPrice * Math.max(1, n(row.menge)));
      inherited.warnings = Array.from(new Set([...(inherited.warnings || []), `Steinstärke ${currentMm} mm aus Basis ${baseMm} mm: nur Materialanteil proportional angepasst.`]));
    }
  }

  const area10to50 = hasAny(text, ["10m2 bis 50m2", "10 m2 bis 50 m2", "10m² bis 50m²", "10 m² bis 50 m²"]);
  const areaOver50 = hasAny(text, ["über 50m2", "ueber 50m2", "über 50 m2", "ueber 50 m2", "über 50m²", "ueber 50m²"]);
  const laborFactor = area10to50 ? 1.12 : areaOver50 ? 1.04 : 1.0;
  if (laborFactor !== 1) {
    for (const line of inherited.costLines) {
      if (["Lohn","Maschinen","Gemeinkosten"].includes(String(line.group))) {
        line.unitPrice = round2(n(line.unitPrice) * laborFactor);
        line.total = round2(n(line.total) * laborFactor);
      }
    }
    inherited.unitPrice = round2(sum(inherited.costLines));
    inherited.total = round2(inherited.unitPrice * Math.max(1, n(row.menge)));
  }
  inherited.riskLevel = "high";
  inherited.confidence = 0.82;
  inherited.calculationStatus = statusFromRisk("high");
  inherited.warnings = Array.from(new Set([
    ...(inherited.warnings || []),
    `Technik aus Bezugs-/Vorposition ${s((baseRow as any).posNr || "")} übernommen; EP vollständig neu aus Urkalkulation berechnet.`,
    area10to50 ? "Kleinflächenfaktor 10–50 m² nur auf Lohn/Maschinen/Gemeinkosten angewendet." : "",
    areaOver50 ? "Flächen >50 m² mit geringem Produktivitätszuschlag kalkuliert." : "",
  ].filter(Boolean)));
  inherited.aiReason += ` Variantenposition: technische Vererbung aus Vorposition, keine Preisvererbung.`;
  return inherited;
}

function resolveTechnicalFreitext20260927(
  row: RlcAutonomousCalcInput,
  ctx: RlcAutonomousProjectContext,
  shortText: string
): RlcAutonomousCalcResult | null {
  if (!/^freitext\b/.test(shortText.trim())) return null;
  const long = String(row.langtext ?? "").trim();
  if (long.length < 20) return null;
  const cleaned = long.replace(/^\s*freitext\s*[:.\-]*\s*/i, "").trim();
  if (!cleaned || /^freitext\b/i.test(cleaned)) return null;
  const synthetic: RlcAutonomousCalcInput = {
    ...row,
    kurztext: cleaned,
    langtext: cleaned,
  };
  const resolved = calculateTiefbauFamilyCatalog(synthetic, ctx, []);
  if (!resolved || resolved.unitPrice <= 0) return null;
  resolved.warnings = Array.from(new Set([
    ...(resolved.warnings || []),
    "Kurztext war nur Freitext-Platzhalter; technische Kalkulation wurde aus dem vollständigen Langtext abgeleitet."
  ]));
  resolved.aiReason += " Freitext-Platzhalter: Langtext als technische Primärquelle verwendet.";
  return resolved;
}


