    return finish(row,ctx,"Wasserhaltung/Pumpe",`Tauchpumpe ca. ${flow} l/s betreiben`,`Tauchpumpe ${flow} l/s`,lines,riskFrom(ctx,"high"),["Förderhöhe, Fördermenge, Stromversorgung, Reserve, Schlauchlänge und Einleitung prüfen."]);
