    const depth = d ? Number(d[1].replace(",", ".")) : 1.5;
    const targetEp = Math.max(46, 46 + Math.max(0, depth - 0.8) * 18.5);
    const factor = targetEp / 56.57;
    addLine(lines, "Material", `Verbauelemente / Vorhaltung für ca. ${depth.toFixed(2)} m Tiefe`, 22.0 * factor, unit, "Marktanker 2026: Rohrgrabenverbau ca. 41–59 EUR/m² bei üblichen Tiefen; größere Tiefen mit steigender Geräte-/Vorhaltebelastung");
