      addLine(lines, "Lohn", "Gefällegerecht verlegen / Muffen herstellen / Höhenkontrolle", base * 0.44, unit);
      addLine(lines, "Maschinen", "Rohrhandling / Verdichtung / Kleingerät", base * 0.06, unit);
      addLine(lines, "Nachunternehmer", "Prüf-/Nebenleistung anteilig", base * 0.02, unit);
