      if (legacyCtx.surfaceAdder > 0) addLine(lines, "Nachunternehmer", `Zuschlag Oberfläche ${legacyCtx.surface}`, legacyCtx.surfaceAdder, unit);
      if (legacyCtx.shoringAdder > 0) addLine(lines, "Maschinen", `Zuschlag Verbau ${legacyCtx.shoring}`, legacyCtx.shoringAdder, unit);
