    addLine(lines, "Material", is500 ? "Aufsatz D400 500x500 inkl. Rahmen/Rost" : "Aufsatz D400 inkl. Rahmen/Rost", is500 ? 300 : 270, unit, "Marktanker 2026: D400 Aufsatz ca. 266–345 EUR/St");
    addLine(lines, "Material", "Auflagering / Adapter / Eimer / Dichtungen", 85, unit);
