    const h = hm ? Number(hm[1].replace(",", ".")) : 6;
    const scale = Math.pow(Math.max(4, h) / 6, 1.15);
    addLine(lines, "Material", `Beton-/Fertigteilfundament für Mast ca. ${h} m inkl. Leerrohre`, 290 * scale, unit);
    addLine(lines, "Lohn", "Aushub / Fundament setzen bzw. betonieren / verfüllen", 120 * Math.pow(scale, 0.55), unit);
    addLine(lines, "Maschinen", "Bagger / Verdichtung / Hebegerät", 75 * Math.pow(scale, 0.60), unit);
