    addLine(lines, "Material", "Beton C25/30 inkl. Bewehrungsanteil", 230, unit);
    addLine(lines, "Lohn", "Schalen / bewehren / betonieren / ausschalen", 75, unit);
    addLine(lines, "Maschinen", "Betonpumpe / Rüttler / Kleingerät", 32, unit);
