    const transport = perM2 ? tonnesPerM2 * 12 : perM ? tonnesPerM * 12 : 12;
    addLine(lines, "Material", `Asphalttragschicht AC 32 T N/S ca. ${cm} cm`, material, unit, "Rohde Asphaltmischgut Preisliste 2026: AC 32 T N/S 72,30 €/t netto ab Werk.");
    addLine(lines, "Nachunternehmer", "Thermotransport Asphaltmischgut", transport, unit);
    addLine(lines, "Lohn", hand ? "Handeinbaukolonne / Rand- und Anschlussarbeiten" : "Einbaukolonne / Rand- und Anschlussarbeiten", labor, unit);
    addLine(lines, "Maschinen", hand ? "Kleingeräte / Walze anteilig" : "Fertiger / Walze / Beschicker anteilig", machine, unit);
    return finish(row, ctx, "Straßenbau/Asphalttragschicht", `Asphalttragschicht AC32 T ca. ${cm} cm ${hand ? "Handeinbau" : "Fertigereinbau"}`, `AC32 T ${cm} cm`, lines, riskFrom(ctx, "medium"), ["Schichtdicke, Mischgutsorte, Flächengröße, Transportentfernung, Verdichtung und Kleinflächenzuschlag prüfen."]);
