    const cmM=(text.match(/(\d+(?:[,.]\d+)?)\s*cm/)||[])[1]; const cm=cmM?Number(cmM.replace(",",".")):18;
    const drain=hasAny(text,["dränbeton","draenbeton"]), lean=hasAny(text,["magerbeton"]), roller=hasAny(text,["walzbeton"]), cement=hasAny(text,["zementverfestigung"]);
